// Fuzzy-match OSM names (e.g. "Westend / Bleichstraße") to our names
// (e.g. "Westend/Bleichstraße"). Used at lookup time.
function _normName(s) {
  return s.toLowerCase()
    .replace(/[äöüß]/g, m => ({ä:'a',ö:'o',ü:'u',ß:'ss'}[m]))
    .replace(/[\/\-\s]+/g, '');
}
function _lookupOSMPolygon(ourName) {
  if (OSM_POLYGONS[ourName]) return OSM_POLYGONS[ourName];
  const target = _normName(ourName);
  for (const k of Object.keys(OSM_POLYGONS)) {
    if (_normName(k) === target) return OSM_POLYGONS[k];
  }
  return null;
}

// Seeded random retained ONLY for deterministic simulated layer values
// (baustellen / aqi / bikePaths / charging). Hexagon generators removed.
let seedValue = 42;
function seededRandom() {
  seedValue = (seedValue * 9301 + 49297) % 233280;
  return seedValue / 233280;
}

// Attach real OSM polygon + simulated layer values to each Ortsbezirk
seedValue = 42;
ORTSBEZIRKE.forEach(o => {
  const poly = _lookupOSMPolygon(o.name);
  if (!poly) console.warn('[Lagebild] No OSM polygon matched for', o.name);
  o.polygon = poly || [];

  // Layer values (deterministic from seed — same as v2.0 to avoid regression)
  o.baustellen = Math.floor(o.pop / 1500 + seededRandom() * 5);
  o.aqi = Math.floor(35 + seededRandom() * 25); // Air quality 35-60
  o.bikePaths = (5 + seededRandom() * 25).toFixed(1); // km
  o.charging = Math.floor(o.pop / 800 + seededRandom() * 3); // E-Ladesäulen (mock; overwritten with real city data below)
});

